test('tooth image upload, persistence and guardian draft omit planned extractions',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="108"]').click();await p.locator('[name=extracted]').check();await p.locator('[data-tooth="109"]').click();await p.locator('[name=extractionPlan]').check();await p.locator('[data-note=procedure]').fill('기록된 실제 처치');await openExtras(p);await p.locator('[data-image-tooth]').selectOption('108');await p.locator('[data-image-caption]').fill('합성 구강 사진');const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a+1cAAAAASUVORK5CYII=','base64');await p.locator('[data-image-file]').setInputFiles({name:'synthetic.png',mimeType:'image/png',buffer:png});await p.locator('[data-image-list] img').waitFor();await p.locator('[data-guide-create]').click();assert.match(await p.locator('[data-guide-text]').inputValue(),/시행 발치: 108번/);assert.doesNotMatch(await p.locator('[data-guide-text]').inputValue(),/109/);await p.locator('[data-dn=save]').click();await p.reload();await openExtras(p);assert.equal(await p.locator('[data-image-list] img').count(),1);assert.match(await p.locator('[data-image-list] figcaption').innerText(),/108번.*합성 구강/s);await p.locator('[data-image-remove]').click();await p.locator('[data-dn=save]').click();assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.images.length),0);await p.close();});
test('related anesthesia shortcut revalidates patient and saves pending dental edits',async()=>{const p=await page();await p.locator('[data-search]').fill('합성');await p.locator('[data-dn=search]').click();await p.locator('[data-pick]').click();await p.locator('[data-dn=save]').click();await p.evaluate(()=>{state.records.push({id:'surgery-one',kind:'surgery',patient_id:'p1',body:{title:'합성 수술'},created_at:'2026-11-01'},{id:'surgery-other',kind:'surgery',patient_id:'other',body:{title:'다른 환자'}});});await openExtras(p);await p.locator('[data-related-load]').click();assert.equal(await p.locator('[data-related-case]').count(),1);await p.locator('[data-note=diagnosis]').fill('이동 전 수정');await p.locator('[data-related-case]').click();assert.deepEqual(await p.evaluate(()=>state.openedSurgery),{id:'surgery-one',patientId:'p1'});assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.diagnosis),'이동 전 수정');await p.evaluate(()=>{delete state.openedSurgery;state.records.find(r=>r.id==='surgery-one').patient_id='other';});await p.locator('[data-related-case]').click();await p.locator('[data-dn-status]').filter({hasText:'같은 환자'}).waitFor();assert.equal(await p.evaluate(()=>state.openedSurgery),undefined);await p.close();});

test('practice opens same-patient surgery from dental and handles stale target errors',async()=>{const p=await page();const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addScriptTag({url:url+'/practice-tools.js'});await p.evaluate(()=>{view.dispose();window.ClinicalWorkspace={mount:(root,a)=>({open:async()=>{},leave:()=>true,resetSelection(){},clear(){},dispose(){},openSurgery:async(id,patientId)=>{state.surgeryNavigation={id,patientId};root.textContent='마취기록 연결';}})};window.practice=PracticeTools.mount(document.querySelector('#root'),{ready:()=>true,identity:()=>state.scope,patient:()=>null,can:()=>true,medical:()=>true,request:api});practice.prepareTab('dental');return practice.open();});await p.locator('[data-dn=new]').click();await p.locator('[data-search]').fill('합성');await p.locator('[data-dn=search]').click();await p.locator('[data-pick]').click();await p.locator('[data-dn=save]').click();await p.evaluate(()=>state.records.push({id:'sx',kind:'surgery',patient_id:'p1',body:{title:'동일 환자 수술'}}));await openExtras(p);await p.locator('[data-related-load]').click();await p.locator('[data-related-case=sx]').click();await p.waitForFunction(()=>state.surgeryNavigation);assert.equal(await p.evaluate(()=>practice.route()),'surgery');assert.deepEqual(await p.evaluate(()=>state.surgeryNavigation),{id:'sx',patientId:'p1'});assert.deepEqual(errors,[]);await p.close();});
