test('refresh restores selected tooth and measurement location only within the same record',async()=>{for(const width of [1440,390]){const p=await page({width,height:900});await fill(p);await p.locator('[data-dn=save]').click();await p.locator('[data-zoom]').selectOption('1');await p.locator('[data-tooth="108"]').click();await p.locator('.dn-tooth-detail').evaluate(e=>e.open=true);await p.locator('[data-pocket-advance]').check();await p.locator('[data-pocket=B]').fill('3');if(width<600)await p.locator('[data-editor-close]').click();await p.locator('[data-dn=save]').click();await p.locator('[data-tooth="108"]').click();await p.locator('[data-pocket=B]').focus();await p.waitForTimeout(150);await p.reload();await p.locator('[data-editor] h3').filter({hasText:'108'}).waitFor();await p.waitForFunction(()=>document.activeElement?.dataset.pocket==='B');assert.equal(await p.locator('[data-pocket=B]').inputValue(),'3');assert.equal(await p.locator('[data-zoom]').inputValue(),'1');assert.ok(await p.locator('[data-pocket-advance]').isChecked());if(width<600)await p.locator('[data-editor-close]').click();await p.locator('[data-dn=back]').click();await p.locator('[data-dn=new]').click();await fill(p);assert.equal(await p.locator('[data-editor] h3').count(),0);await p.close();}});
test('different fields on the same tooth save automatically after another account edits',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="108"]').click();await p.locator('[data-grade=gi][data-value="1"]').click();await p.locator('[data-dn=save]').click();await p.evaluate(()=>{state.records[0].body.dentalChart.teeth['108'].note='다른 직원 메모';state.records[0].revision++;});await p.locator('[data-grade=gi][data-value="2"]').click();await p.locator('[data-dn=save]').click();await p.locator('[data-dn-status]').filter({hasText:'저장됨'}).waitFor();assert.equal(await p.locator('.dn-conflict').count(),0);assert.deepEqual(await p.evaluate(()=>state.records[0].body.dentalChart.teeth['108']),{gi:2,note:'다른 직원 메모'});await p.close();});
test('removed image can be restored after autosave with a fresh valid upload reference',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="108"]').click();const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a+1cAAAAASUVORK5CYII=','base64');await p.locator('[data-editor-image-file]').setInputFiles({name:'test.png',mimeType:'image/png',buffer:png});await p.locator('[data-editor-images] img').waitFor();await p.locator('[data-dn=save]').click();const id=await p.evaluate(()=>state.records[0].body.dentalChart.images[0].id);await p.locator('[data-editor-images] [data-image-remove]').click();await p.locator('[data-editor-images] [data-image-undo]').waitFor();await p.locator('[data-dn=save]').click();assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.images.length),0);await p.locator('[data-editor-images] [data-image-undo]').click();await p.locator('[data-dn=save]').click();assert.notEqual(await p.evaluate(()=>state.records[0].body.dentalChart.images[0].id),id);assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.images[0].toothId),'108');await p.reload();await p.locator('[data-tooth="108"]').click();await p.locator('[data-editor-images] img').waitFor();await p.close();});
test('finishing summary saves completion without forcing unrecorded teeth or clearing plans',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="108"]').click();await p.locator('[name=extractionPlan]').check();assert.match(await p.locator('[data-finish]').innerText(),/예정으로 남은 치아 108/);await p.locator('[data-complete]').click();await p.locator('[data-dn-status]').filter({hasText:'저장됨'}).waitFor();assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.clinicalStatus),'complete');assert.equal(await p.evaluate(()=>Object.keys(state.records[0].body.dentalChart.teeth).length),1);assert.ok(await p.evaluate(()=>state.records[0].body.dentalChart.teeth['108'].extractionPlan));await p.locator('[data-note=diagnosis]').fill('수정 소견');assert.match(await p.locator('[data-clinical-badge]').innerText(),/완료 후 수정/);await p.close();});
test('stale guardian print offers update before printing and leaves internal notice off paper',async()=>{const p=await page();await fill(p);await openExtras(p);await p.locator('[data-guide-create]').click();await p.locator('[data-note=diagnosis]').fill('변경 진단');await p.locator('[data-dn=print]').click();await p.locator('[data-print-target]').selectOption('guardian');assert.ok(await p.locator('[data-print-warning]').isVisible());await p.locator('[data-print-update]').click();assert.ok(await p.locator('[data-guide-proposal]').isVisible());await p.locator('[data-guide-review-apply]').click();await p.locator('[data-dn=print]').click();assert.ok(!await p.locator('[data-print-warning]').isVisible());await p.locator('[data-print-cancel]').click();await p.close();});
test('Clinic dental width matches clinical workspace and only one visible page title remains',async()=>{for(const width of [1920,1366,390]){const p=await page({width,height:900});await fill(p);await p.addStyleTag({content:fs.readFileSync(path.join(root,'clinical-workspace.css'),'utf8')});await p.evaluate(()=>{document.body.classList.add('clinic-navigation-ready');const d=document.querySelector('#root'),shell=document.createElement('main');shell.id='practiceRoot';shell.className='pt';d.before(shell);shell.append(d);const h=document.createElement('h1');h.textContent='치과기록지';shell.before(h);const compare=document.createElement('div');compare.className='cl-workspace';compare.dataset.widthReference='';shell.append(compare);});assert.equal(await p.getByRole('heading',{name:'치과기록지',exact:true}).count(),1);const widths=await p.evaluate(()=>[document.querySelector('.dn').getBoundingClientRect().width,document.querySelector('[data-width-reference]').getBoundingClientRect().width]);assert.ok(Math.abs(widths[0]-widths[1])<1,JSON.stringify(widths));assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await p.screenshot({path:path.join(root,'../dental15-width-'+width+'.png'),fullPage:true});await p.close();}});

test('returning from a record preserves search, loaded pages and list position',async()=>{const p=await page();await fill(p);await p.locator('[data-dn=save]').click();await p.evaluate(()=>{const seed=structuredClone(state.records[0]);state.records=Array.from({length:120},(_,i)=>({...structuredClone(seed),id:'case'+i,patient:{name:'합성 '+i},body:{...structuredClone(seed.body),dentalChart:{...structuredClone(seed.body.dentalChart),diagnosis:'진단 '+i}}}));const original=api;view.dispose();sessionStorage.removeItem('carestep.dental.resume.'+state.scope);view=DentalRecord.mount(document.querySelector('#root'),{ready:()=>true,identity:()=>state.scope,can:()=>true,medical:()=>true,request:async(path,o)=>{if(path.startsWith('/practice/clinical/dental')){const u=new URL('https://test'+path),offset=Number(u.searchParams.get('cursor')||0),found=state.records.filter(r=>!u.searchParams.get('q')||r.body.dentalChart.diagnosis.includes(u.searchParams.get('q')));return {items:found.slice(offset,offset+50).map(r=>({id:r.id,patient:r.patient,date:r.body.dentalChart.date,species:r.body.species,diagnosis:r.body.dentalChart.diagnosis})),next:offset+50<found.length?String(offset+50):null};}return original(path,o);}});view.open();});await p.locator('[data-dn-query]').fill('진단');await p.locator('[data-list-search] button').click();await p.locator('[data-dn=more]').click();assert.equal(await p.locator('[data-record]').count(),100);await p.locator('[data-record="case80"]').scrollIntoViewIfNeeded();const y=await p.evaluate(()=>scrollY);await p.locator('[data-record="case80"]').click();await p.locator('[data-dn=back]').click();await p.waitForFunction(()=>document.querySelectorAll('[data-record]').length===100);assert.equal(await p.locator('[data-dn-query]').inputValue(),'진단');await p.waitForTimeout(50);assert.ok(Math.abs(await p.evaluate(()=>scrollY)-y)<50);await p.close();});
